import numpy as np

def minimize_quadratic(lr, n_steps=50, start=0.0):
    w = start
    for _ in range(n_steps):
        grad = 2 * (w - 3)
        w = w - lr * grad
    return w

for lr in [0.001, 0.1, 1.5]:
    final_w = minimize_quadratic(lr)
    print(f'lr={lr:.3f} -> final w = {final_w:.4f}  (true min = 3.0)')
